source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)
            local = {(rr-r0, cc-c0) for rr, cc in cells}
            frame = {(rr, cc) for rr in range(r1-r0+1) for cc in range(c1-c0+1)
                     if rr in (0, r1-r0) or cc in (0, c1-c0)}
            goes_up = local == frame
            objects.append({'color': color, 'cells': cells, 'r0': r0, 'r1': r1,
                            'up': goes_up})

    result = [[0] * w for _ in range(h)]
    placed = []

    def fits(obj, top):
        coords = {(top + rr - obj['r0'], cc) for rr, cc in obj['cells']}
        return all(0 <= rr < h and not any((rr, cc) in other for other in placed) for rr, cc in coords)

    # Frames collect at the top, preserving their original top-to-bottom order.
    for obj in sorted((o for o in objects if o['up']), key=lambda o: o['r0']):
        top = 0
        while top <= obj['r0'] and not fits(obj, top):
            top += 1
        coords = {(top + rr - obj['r0'], cc) for rr, cc in obj['cells']}
        placed.append(coords)
        for rr, cc in coords:
            result[rr][cc] = obj['color']

    # Other shapes collect at the bottom, preserving their original bottom-to-top order.
    for obj in sorted((o for o in objects if not o['up']), key=lambda o: o['r1'], reverse=True):
        height = obj['r1'] - obj['r0'] + 1
        top = h - height
        while top >= 0 and not fits(obj, top):
            top -= 1
        coords = {(top + rr - obj['r0'], cc) for rr, cc in obj['cells']}
        placed.append(coords)
        for rr, cc in coords:
            result[rr][cc] = obj['color']
    return result
'''
